/**
 * "<display name>'s workspace", within the organization name limit. A display
 * name too long for that is cut (by code point, so no surrogate pair is split)
 * until the whole name fits, so the result still ends in the suffix.
 */
function firstWorkspaceName(displayName: string): string {
  const budget = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_SUFFIX.length;
  let kept = "";
  for (const character of displayName.trim()) {
    if (kept.length + character.length > budget) break;
    kept += character;
  }
  return `${kept.trimEnd()}${WORKSPACE_SUFFIX}`;
}

/** SQLite's unique-index refusal on `users.email`; drizzle keeps it on `cause`. */
function isEmailTakenError(error: unknown): boolean {
  const cause = error instanceof Error ? error.cause : undefined;
  return [error, cause].some(
    (candidate) =>
      candidate instanceof Error &&
      /UNIQUE constraint failed: users\.email/.test(candidate.message),
  );
}

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other. Everything that can
 * refuse the sign-up (the throttle, a duplicate address) is decided, and the
 * workspace name and slug are derived, before the first write. A name can
 * therefore never leave a user row without its workspace. See ADR 0003.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(REGISTER_BUCKET, verdict.resetAt);
  }

  if (await userRepo.findUserByEmail(input.email)) {
    throw new DuplicateEmailError();
  }

  const name = firstWorkspaceName(input.name);
  const slugBase = workspaceSlugBase(input.name);
  const slug = uniqueSlug(slugBase, await orgRepo.listTakenOrgSlugs(slugBase));

  const passwordHash = await hashPassword(input.password);
  let user: User;
  try {
    user = await userRepo.insertUser({
      email: input.email,
      name: input.name,
      passwordHash,
    });
  } catch (error) {
    // A concurrent sign-up with the same address can pass the lookup above
    // and then lose on the unique index.
    if (isEmailTakenError(error)) throw new DuplicateEmailError();
    throw error;
  }

  const org = await createOrganization(user.id, { name, slug, plan: "free" });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

