function firstWorkspaceName(displayName: string): string {
  const budget = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_SUFFIX.length;
  let kept = "";
  for (const character of displayName.trim()) {
    if (kept.length + character.length > budget) break;
    kept += character;
  }
  return `${kept.trimEnd()}${WORKSPACE_SUFFIX}`;
}

/** SQLite's unique-index refusal on `users.email`; drizzle keeps it on `cause`. */
function isEmailTakenError(error: unknown): boolean {
  const cause = error instanceof Error ? error.cause : undefined;
  return [error, cause].some(
    (candidate) =>
      candidate instanceof Error &&
      /UNIQUE constraint failed: users\.email/.test(candidate.message),
  );
}

