/**
 * Sign-up rules from docs/adr/0003-account-creation.md: first-workspace naming
 * and slugs, case-insensitive addresses, duplicate refusal and throttling.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { DuplicateEmailError, RateLimitedError, toAppError } from "@/lib/errors";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { createOrganizationSchema } from "@/schemas/organization";
import type { RegisterInput } from "@/schemas/auth";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as authService from "@/server/services/auth-service";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

/** The anonymous bucket owner the auth service charges (see auth-service.ts). */
const ANONYMOUS = "00000000000000000000000000" as OrgId;
const PASSWORD = "Correct-Horse-9x";
const WORKSPACE_SUFFIX = "'s workspace";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

function signUp(overrides: Partial<RegisterInput> = {}) {
  return authService.register({
    name: "Taylor",
    email: "taylor@auth-signup.test",
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
    ...overrides,
  });
}

/** Spends the bucket until the limiter refuses, so the next attempt is throttled. */
function exhaust(bucketKey: string): void {
  for (let i = 0; i < 10_000; i += 1) {
    if (!consumeAllowed(bucketKey)) return;
  }
  throw new Error(`bucket ${bucketKey} never refused`);
}

function consumeAllowed(bucketKey: string): boolean {
  let allowed = true;
  void consumeRateLimit(ANONYMOUS, bucketKey).then((verdict) => {
    allowed = verdict.allowed;
  });
  return allowed;
}

describe("services/auth-service sign-up: first workspace", () => {
  it("gives a reserved word the same treatment as any other name", async () => {
    const { org } = await signUp({
      name: "Admin",
      email: "admin-person@auth-signup.test",
