/**
 * Sign-up rules from docs/adr/0003-account-creation.md: first-workspace naming
 * and slugs, case-insensitive addresses, duplicate refusal and throttling.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { DuplicateEmailError, RateLimitedError, toAppError } from "@/lib/errors";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { createOrganizationSchema } from "@/schemas/organization";
import type { RegisterInput } from "@/schemas/auth";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as authService from "@/server/services/auth-service";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

/** The anonymous bucket owner the auth service charges (see auth-service.ts). */
const ANONYMOUS = "00000000000000000000000000" as OrgId;
const PASSWORD = "Correct-Horse-9x";
const WORKSPACE_SUFFIX = "'s workspace";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

function signUp(overrides: Partial<RegisterInput> = {}) {
  return authService.register({
    name: "Taylor",
    email: "taylor@auth-signup.test",
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
    ...overrides,
  });
}

/** Spends the bucket until the limiter refuses, so the next attempt is throttled. */
async function exhaust(bucketKey: string): Promise<void> {
  for (let i = 0; i < 10_000; i += 1) {
    const verdict = await consumeRateLimit(ANONYMOUS, bucketKey);
    if (!verdict.allowed) return;
  }
  throw new Error(`bucket ${bucketKey} never refused`);
}

describe("services/auth-service sign-up: first workspace", () => {
  it("gives a reserved word the same treatment as any other name", async () => {
    const { org } = await signUp({
      name: "Admin",
      email: "admin-person@auth-signup.test",
    });

    expect(org.slug).toBe("admin-2");
    expect(org.name).toBe(`Admin${WORKSPACE_SUFFIX}`);
  });

  it("uses a name of two characters, and falls back to `workspace` for one", async () => {
    const short = await signUp({ name: "Al", email: "al@auth-signup.test" });
    const single = await signUp({ name: "J", email: "j@auth-signup.test" });

    expect(short.org.slug).toBe("al");
    expect(single.org.slug).toBe("workspace");
    expect(single.org.name).toBe(`J${WORKSPACE_SUFFIX}`);
  });

  it("falls back to `workspace` for a name with no Latin letters", async () => {
    const { org } = await signUp({ name: "山田", email: "yamada@auth-signup.test" });

    expect(org.slug).toBe("workspace");
    expect(org.name).toBe(`山田${WORKSPACE_SUFFIX}`);
  });

  it("shortens an over-long display name so the workspace name fits the limit", async () => {
    const { org } = await signUp({
      name: "x".repeat(80),
      email: "long-name@auth-signup.test",
    });

    expect(org.name.endsWith(WORKSPACE_SUFFIX)).toBe(true);
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(
      createOrganizationSchema.safeParse({ name: org.name, slug: org.slug }).success,
    ).toBe(true);
  });
});

describe("services/auth-service sign-up: addresses", () => {
  it("stores and matches an address case-insensitively", async () => {
    const { user } = await signUp({ email: "Alice@Example.com" });
    expect(user.email).toBe("alice@example.com");

    const signedIn = await authService.login({
      email: "ALICE@example.COM",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(signedIn.user.id).toBe(user.id);
  });

  it("refuses a second account for the same address in any spelling, as a conflict", async () => {
    await signUp({ email: "dup@auth-signup.test", name: "Dana" });

    const error = await signUp({
      email: "DUP@Auth-Signup.test",
      name: "Imposter",
    }).catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(DuplicateEmailError);
    expect(toAppError(error).code).toBe("conflict");
    expect(await orgRepo.findOrgBySlug("imposter")).toBeNull();
  });
});

describe("services/auth-service sign-up: throttling", () => {
  it("refuses a sign-up over the limit as rate_limited, writing nothing", async () => {
    await exhaust("auth:register");

    const error = await signUp({ email: "throttled@auth-signup.test" }).catch(
      (caught: unknown) => caught,
    );

    expect(error).toBeInstanceOf(RateLimitedError);
    expect(toAppError(error).code).toBe("rate_limited");
    expect(await userRepo.findUserByEmail("throttled@auth-signup.test")).toBeNull();
  });

  it("reports a throttled sign-in as rate_limited rather than an internal error", async () => {
    await signUp({ email: "waiting@auth-signup.test" });
    await exhaust("auth:login");

    const error = await authService
      .login({ email: "waiting@auth-signup.test", password: PASSWORD, rememberMe: false })
      .catch((caught: unknown) => caught);

    expect(toAppError(error).code).toBe("rate_limited");
  });

  it("keeps a throttled password-reset request silent", async () => {
    await exhaust("auth:password-reset");

    await expect(
      authService.requestPasswordReset({ email: "waiting@auth-signup.test" }),
    ).resolves.toBeUndefined();
  });

  it("refuses a throttled reset confirmation as rate_limited", async () => {
    await exhaust("auth:password-reset");

    const error = await authService
      .confirmPasswordReset({
        token: "t".repeat(32),
        password: PASSWORD,
        confirmPassword: PASSWORD,
      })
      .catch((caught: unknown) => caught);

    expect(toAppError(error).code).toBe("rate_limited");
  });
});

